import { Router } from "express";
import { authMiddleware } from "../../middlewares/auth.middleware.js";
import { requireOnboarding } from "../../middlewares/onboarding.middleware.js";
import { portalRoleMiddleware } from "../../middlewares/role.middleware.js";
import { upload } from "../../middlewares/upload.middleware.js";
import { uploadFile } from "../../controllers/media/media.controller.js";
import { getMyVerification, updateMyVerification, deleteMyVerification } from "../../controllers/verification/verification.controller.js";
import { getClientDashboard, getClientProfile, updateClientProfile, listClientProjects, getClientPipeline, createClientProject, getClientProject, updateClientProject, deleteClientProject, listProjectApplications, acceptProposal, rejectProposal, interviewProposal, listClientContracts, listClientTasks, addClientTask, updateClientTask, deleteClientTask, listClientMeetings, createClientMeeting, listClientMessages, createClientMessage, getClientWallet, fundClientWallet, withdrawClientWallet, listClientInvoices, listClientPayments, listClientReviews, createClientReview, getClientAnalytics, listClientNotifications, markAllClientNotificationsRead, markClientNotificationRead, getClientSettings, updateClientSettings, listClientSubscriptions, purchaseClientSubscription, listClientDocuments, addClientDocument, deleteClientDocument, listClientTeam, listClientInvitations, addClientTeamMember, deleteClientTeamMember, listClientPipeline, getClientReferrals, getClientReports, listClientApiKeys, generateClientApiKey, revokeClientApiKey, listClientApplications, listSavedFreelancers, toggleSavedFreelancer, removeSavedFreelancer, shareFreelancer, } from "../../controllers/client/client.controller.js";
const router = Router();
router.use(authMiddleware);
router.use(requireOnboarding);
router.use(portalRoleMiddleware(["client"]));
router.get("/dashboard", getClientDashboard);
router.get("/profile", getClientProfile);
router.patch("/profile", updateClientProfile);
router.put("/profile", updateClientProfile);
router.get("/verification", getMyVerification);
router.patch("/verification", updateMyVerification);
router.delete("/verification", deleteMyVerification);
router.get("/projects", listClientProjects);
router.post("/projects/search", listClientProjects);
router.get("/pipeline", getClientPipeline);
router.post("/projects", createClientProject);
router.get("/projects/:id", getClientProject);
router.patch("/projects/:id", updateClientProject);
router.put("/projects/:id", updateClientProject);
router.delete("/projects/:id", deleteClientProject);
router.get("/projects/:id/applications", listProjectApplications);
router.get("/applications", listClientApplications);
router.post("/proposals/:id/accept", acceptProposal);
router.post("/proposals/:id/reject", rejectProposal);
router.post("/proposals/:id/interview", interviewProposal);
router.get("/contracts", listClientContracts);
router.get("/tasks", listClientTasks);
router.post("/tasks", addClientTask);
router.patch("/tasks/:id", updateClientTask);
router.put("/tasks/:id", updateClientTask);
router.delete("/tasks/:id", deleteClientTask);
router.get("/meetings", listClientMeetings);
router.post("/meetings", createClientMeeting);
router.get("/messages", listClientMessages);
router.post("/messages", createClientMessage);
router.get("/wallet", getClientWallet);
router.post("/wallet/fund", fundClientWallet);
router.post("/wallet/withdraw", withdrawClientWallet);
router.get("/invoices", listClientInvoices);
router.get("/payments", listClientPayments);
router.get("/reviews", listClientReviews);
router.post("/reviews", createClientReview);
router.get("/analytics", getClientAnalytics);
router.get("/notifications", listClientNotifications);
router.patch("/notifications/read-all", markAllClientNotificationsRead);
router.patch("/notifications/:id/read", markClientNotificationRead);
router.get("/settings", getClientSettings);
router.patch("/settings", updateClientSettings);
router.get("/subscriptions", listClientSubscriptions);
router.post("/subscriptions/purchase", purchaseClientSubscription);
router.get("/documents", listClientDocuments);
router.post("/documents", addClientDocument);
router.delete("/documents/:id", deleteClientDocument);
router.get("/team", listClientTeam);
router.get("/invitations", listClientInvitations);
router.post("/team", addClientTeamMember);
router.delete("/team/:id", deleteClientTeamMember);
router.get("/pipeline", listClientPipeline);
router.get("/referrals", getClientReferrals);
router.get("/reports", getClientReports);
router.get("/api-keys", listClientApiKeys);
router.post("/api-keys", generateClientApiKey);
router.delete("/api-keys/:id", revokeClientApiKey);
router.post("/media/upload", upload.single("file"), uploadFile);
// Saved freelancers (bookmark)
router.get("/freelancers/saved", listSavedFreelancers);
router.post("/freelancers/save", toggleSavedFreelancer);
router.delete("/freelancers/saved/:id", removeSavedFreelancer);
// Share freelancer (track)
router.post("/freelancers/share", shareFreelancer);
export default router;
